#include "mspa/decision/response_curve.hpp"
#include <algorithm>
#include <cmath>
namespace mspa {Result<void>ResponseCurve::set_points(std::vector<CurvePoint>p){if(p.empty()){points_.clear();return {};}for(const auto&x:p)if(!std::isfinite(x.x)||!std::isfinite(x.y))return make_error(ErrorCode::InvalidArgument,"curve contains non-finite point");std::stable_sort(p.begin(),p.end(),[](auto&a,auto&b){return a.x<b.x;});for(std::size_t i=1;i<p.size();++i)if(p[i].x==p[i-1].x)return make_error(ErrorCode::InvalidArgument,"curve x values must be unique");points_=std::move(p);return {};}void ResponseCurve::clear()noexcept{points_.clear();}float ResponseCurve::evaluate(float x)const noexcept{if(points_.empty())return x;if(x<=points_.front().x)return points_.front().y;if(x>=points_.back().x)return points_.back().y;auto hi=std::upper_bound(points_.begin(),points_.end(),x,[](float v,const CurvePoint&p){return v<p.x;});auto lo=hi-1;float t=(x-lo->x)/(hi->x-lo->x);return lo->y+t*(hi->y-lo->y);}const std::vector<CurvePoint>&ResponseCurve::points()const noexcept{return points_;}std::size_t ResponseCurve::size()const noexcept{return points_.size();}}
